        {
            "courier": "DPD",
            "title": "DPD przesyłka o długości 250-300 cm",
            "message": "<p>Uwaga! Możliwość wysyłki przesyłek o długości od 250 cm do 300 cm i sumie pozostałych dwóch boków do 60 cm zależeć będzie od rejonu. Jeśli przewoźnik na danym rejonie będzie dysponować autem umożliwiającym transport takiej przesyłki zost…",
            "type": "MESSAGE",
            "severity": "SUCCESS",
            "priority": 6
        },
        {
            "courier": "DPD",
            "title": "Płatność kartą za pobranie ",
            "message": "<p>Uwaga! Przewoźnik nalicza opłatę w sytuacji, gdy odbiorca opłaci pobranie kartą płatniczą. Kwota naliczana jest po zrealizowaniu zlecenia zgodnie z cennikiem na stronie.&nbsp;</p>",
            "type": "MESSAGE",
            "severity": "WARNING",
            "priority": 1
        }
    ]
}

